//! Embedded columns, the parts every role shares: the embedding model
//! aliases (`ai.embedding_models`), the `ai.embedding.*` keys, the
//! catalog rows ([`store`]) and the metrics.
//!
//! An embedded column is a `VECTOR(n)` column declared as the embedding
//! of an expression over its row (`GENERATED BY EMBEDDING(...) USING MODEL
//! '<alias>'`). The gateway checks the declaration and records it in the
//! tenant catalog; the worker's `ai_embed` job fills it from the change
//! feed and backfills existing rows.
//!
//! **Models.** An alias names a model: `local:bge-small` is the bundled
//! model, run in the worker's process, so nothing leaves SprigDB. A
//! `provider/model` alias names a provider's embedding model; providers
//! aren't wired to embedded columns yet, so the gateway refuses them
//! (39997) — see [`ModelRef::is_local`].
//!
//! | Key | Default | Scopes |
//! |---|---|---|
//! | `ai.embedding_models` | the bundled model | global |
//! | `ai.embedding.backfill_rows_per_s` | `500` | tenant, global |
//! | `ai.embedding.rows_per_s` | `2000` | tenant, global |
//! | `ai.embedding.batch_rows` | `64` | global |
//! | `ai.embedding.max_input_bytes` | `65536` | global |

pub mod store;

use std::borrow::Cow;

use serde::{Deserialize, Serialize};
use serde_json::Value;
use sprig_common::{SprigCode, SprigError};
use sprig_settings::{Apply, HardBounds, Scopes, Setting};

type Text = Cow<'static, str>;

/// Tenant and global.
const TENANT_GLOBAL: Scopes = Scopes(0b10_0100);
/// Global only.
const GLOBAL: Scopes = Scopes(0b10_0000);

/// The bundled model's alias.
pub const LOCAL_ALIAS: &str = "local:bge-small";

/// The default of `ai.embedding_models`.
pub const DEFAULT_MODELS: &str =
    r#"{"local:bge-small":{"provider":"local","model":"BAAI/bge-small-en-v1.5","dimensions":384}}"#;

macro_rules! key {
    ($(#[$doc:meta])* $name:ident: $t:ty = $key:literal, $default:expr, $scopes:expr, $hard:expr, $op:expr, $text:literal) => {
        $(#[$doc])*
        pub static $name: Setting<$t> = Setting {
            key: $key,
            default: $default,
            scopes: $scopes,
            hard: $hard,
            apply: Apply::Live,
            operator_only: $op,
            owner: 56,
            doc: $text,
        };
        sprig_settings::register!($name);
    };
}

key!(
    /// `ai.embedding_models`.
    MODELS: Text = "ai.embedding_models", Cow::Borrowed(DEFAULT_MODELS), GLOBAL, HardBounds::NONE, true,
    "Embedding model aliases offered to tenants, a JSON object: alias to {provider, model, dimensions}; provider local is the bundled model"
);
key!(
    /// `ai.embedding.backfill_rows_per_s`.
    BACKFILL_ROWS_PER_S: u64 = "ai.embedding.backfill_rows_per_s", 500, TENANT_GLOBAL,
    HardBounds::range(1, 1_000_000), false,
    "Existing rows an embedded column's backfill embeds per second at most"
);
key!(
    /// `ai.embedding.rows_per_s`.
    ROWS_PER_S: u64 = "ai.embedding.rows_per_s", 2000, TENANT_GLOBAL,
    HardBounds::range(1, 1_000_000), false,
    "Rows one embedded column embeds per second at most, changes and backfill together"
);
key!(
    /// `ai.embedding.batch_rows`.
    BATCH_ROWS: u64 = "ai.embedding.batch_rows", 64, GLOBAL, HardBounds::range(1, 1024), true,
    "Inputs the embedding worker sends to the model at once"
);
key!(
    /// `ai.embedding.max_input_bytes`.
    MAX_INPUT_BYTES: u64 = "ai.embedding.max_input_bytes", 65_536, GLOBAL,
    HardBounds::range(256, 16_777_216), true,
    "A source value longer than this is cut to this many bytes before it is embedded"
);

/// What an alias names.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ModelRef {
    /// The alias, as `USING MODEL` names it.
    pub alias: String,
    /// `local`, or a provider record's name.
    pub provider: String,
    /// The model's own name.
    pub model: String,
    /// Its vectors' dimensions.
    pub dimensions: u32,
}

impl ModelRef {
    /// The bundled model.
    #[must_use]
    pub fn local() -> Self {
        Self {
            alias: LOCAL_ALIAS.to_owned(),
            provider: "local".to_owned(),
            model: "BAAI/bge-small-en-v1.5".to_owned(),
            dimensions: 384,
        }
    }

    /// Whether it runs in SprigDB's own processes.
    #[must_use]
    pub fn is_local(&self) -> bool {
        self.provider == "local"
    }
}

/// 39997 with `msg`.
#[must_use]
pub fn failed(msg: impl Into<String>) -> SprigError {
    SprigError::new(SprigCode::EmbeddingFailed, msg)
}

/// The aliases of `ai.embedding_models`' value `json`, in name order.
///
/// # Errors
///
/// 39997 when the value isn't an object of `{provider, model,
/// dimensions}`.
pub fn models(json: &str) -> Result<Vec<ModelRef>, SprigError> {
    let v: Value = serde_json::from_str(json)
        .map_err(|e| failed(format!("ai.embedding_models isn't JSON: {e}")))?;
    let obj = v
        .as_object()
        .ok_or_else(|| failed("ai.embedding_models must be a JSON object"))?;
    let mut out = Vec::with_capacity(obj.len());
    for (alias, m) in obj {
        let get = |k: &str| {
            m[k].as_str()
                .map(str::to_owned)
                .ok_or_else(|| failed(format!("ai.embedding_models: {alias} has no {k}")))
        };
        let dimensions = m["dimensions"]
            .as_u64()
            .and_then(|d| u32::try_from(d).ok())
            .filter(|d| (1..=16_383).contains(d))
            .ok_or_else(|| {
                failed(format!(
                    "ai.embedding_models: {alias} needs dimensions from 1 to 16383"
                ))
            })?;
        out.push(ModelRef {
            alias: alias.clone(),
            provider: get("provider")?,
            model: get("model")?,
            dimensions,
        });
    }
    Ok(out)
}

/// The model `alias` names in `ai.embedding_models`' value `json`.
///
/// # Errors
///
/// 39997 for an alias the value doesn't list (the message names the ones
/// it does), or a malformed value.
pub fn resolve(alias: &str, json: &str) -> Result<ModelRef, SprigError> {
    let all = models(json)?;
    if let Some(m) = all.iter().find(|m| m.alias == alias) {
        return Ok(m.clone());
    }
    let names: Vec<&str> = all.iter().map(|m| m.alias.as_str()).collect();
    Err(failed(format!(
        "no embedding model is named '{alias}'; ai.embedding_models offers {}",
        if names.is_empty() {
            "none".to_owned()
        } else {
            names.join(", ")
        }
    )))
}

/// The worker's metrics.
pub mod metrics {
    /// Rows this process's embedding jobs have waiting: changes read and
    /// not yet written, plus their backfills' estimates.
    pub fn backlog(rows: u64) {
        #[allow(clippy::cast_precision_loss)]
        metrics::gauge!("sprig_ai_embedding_backlog").set(rows as f64);
    }

    /// Rows handled: `result` is `embedded`, `cleared` (no source),
    /// `skipped` (already current), `superseded` (the row changed again
    /// first) or `failed`.
    pub fn rows(model: &str, result: &'static str, n: u64) {
        if n > 0 {
            metrics::counter!("sprig_ai_embedding_rows_total", "model" => model.to_owned(), "result" => result)
                .increment(n);
        }
    }

    /// One model batch's time.
    pub fn seconds(model: &str, secs: f64) {
        metrics::histogram!("sprig_ai_embedding_seconds", "model" => model.to_owned()).record(secs);
    }

    /// Cutovers of re-embeddings: `result` is `done` or `failed`.
    pub fn cutovers(result: &'static str) {
        metrics::counter!("sprig_ai_embedding_cutovers_total", "result" => result).increment(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_default_offers_the_bundled_model() {
        let m = resolve(LOCAL_ALIAS, DEFAULT_MODELS).unwrap();
        assert_eq!(m, ModelRef::local());
        assert!(m.is_local());
        assert_eq!(MODELS.default, DEFAULT_MODELS);
    }

    #[test]
    fn unknown_and_malformed_aliases_fail_with_39997() {
        let e = resolve("openai/x", DEFAULT_MODELS).unwrap_err();
        assert_eq!(e.code(), Some(SprigCode::EmbeddingFailed));
        assert!(e.to_string().contains("local:bge-small"), "{e}");
        for bad in [
            "[]",
            "{",
            r#"{"a":{"provider":"local","model":"m"}}"#,
            r#"{"a":{"provider":"local","model":"m","dimensions":0}}"#,
        ] {
            assert!(models(bad).is_err(), "{bad}");
        }
        let two = r#"{"openai/small":{"provider":"openai","model":"text-embedding-3-small","dimensions":1536},"local:bge-small":{"provider":"local","model":"BAAI/bge-small-en-v1.5","dimensions":384}}"#;
        let m = resolve("openai/small", two).unwrap();
        assert!(!m.is_local());
        assert_eq!(m.dimensions, 1536);
    }
}
